for (const [locale, labels] of Object.entries(UI_COMMAND_TRANSLATION_LISTS)) {
  const englishLabels = Object.values(UI_COMMAND_LABELS);
  if (labels.length !== englishLabels.length) throw new Error(`Command catalog locale count mismatch: ${locale}`);
  UI_COMMAND_TRANSLATIONS[locale] = Object.fromEntries(englishLabels.map((english, index) => [english, labels[index]]));
}
UI_COMMAND_TRANSLATIONS.esMX = UI_COMMAND_TRANSLATIONS.esES;

function uiCommandLabel(locale, english) {
  if (locale === "enUS") return english;
  return UI_COMMAND_TRANSLATIONS[locale]?.[english] ?? english;
}

Object.assign(CATALOG_ROWS, Object.fromEntries(Object.entries(UI_COMMAND_LABELS).map(([key, english]) => [
  key, SUPPORTED_LOCALES.map((locale) => uiCommandLabel(locale, english))
])));

