for (const [locale, labels] of Object.entries(UI_SHORTCUT_TRANSLATION_LISTS)) {
  const entries = Object.entries(UI_SHORTCUT_TEXT);
  if (labels.length !== entries.length) throw new Error(`Shortcut catalog locale count mismatch: ${locale}`);
  const localeIndex = SUPPORTED_LOCALES.indexOf(locale);
  entries.forEach(([key], index) => { CATALOG_ROWS[key][localeIndex] = labels[index]; });
}
for (const [key] of Object.entries(UI_SHORTCUT_TEXT)) CATALOG_ROWS[key][SUPPORTED_LOCALES.indexOf("esMX")] = CATALOG_ROWS[key][SUPPORTED_LOCALES.indexOf("esES")];

